//! Static question bank with real curriculum content for 8 domains.
//! Questions are organized by topic slug and tagged with difficulty + week availability.

/// A static question entry in the bank.
#[derive(Debug, Clone)]
pub struct BankQuestion {
    pub topic_slug: &'static str,
    pub question_type: &'static str,
    pub difficulty: f64,
    pub week_min: u32,
    pub question_text: &'static str,
    pub options: [&'static str; 4],
    pub correct_answer: &'static str,
    pub is_checkpoint: bool,
}

/// Look up questions matching a topic name. Uses the default_topics mapping
/// to resolve the canonical slug, then searches the bank.
pub fn find_by_topic(topic_name: &str) -> Vec<&'static BankQuestion> {
    // Look up the canonical slug from the topic name mapping
    let slug = crate::models::topic::default_topics()
        .into_iter()
        .find(|(_, name, _)| *name == topic_name)
        .map(|(_, _, s)| s.to_string());

    match slug {
        Some(s) => QUESTIONS.iter().filter(|q| q.topic_slug == s).collect(),
        None => Vec::new(),
    }
}

/// Look up questions for a specific topic slug directly.
pub fn find_by_slug(slug: &str) -> Vec<&'static BankQuestion> {
    QUESTIONS.iter().filter(|q| q.topic_slug == slug).collect()
}

