#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_question_count() {
        assert!(QUESTIONS.len() >= 60, "Should have at least 60 questions, got {}", QUESTIONS.len());
    }

    #[test]
    fn test_find_by_slug() {
        let qs = find_by_slug("python-ds");
        assert!(qs.len() >= 4, "python-ds should have at least 4 questions");
    }

    #[test]
    fn test_find_by_topic_name() {
        let qs = find_by_topic("Python for Data Science");
        assert!(!qs.is_empty(), "Should find questions by topic name");
    }

    #[test]
    fn test_find_by_topic_resolves_names() {
        let qs = find_by_topic("SQL Fundamentals");
        assert!(!qs.is_empty(), "Should resolve 'SQL Fundamentals' to slug 'sql-fundamentals'");
        let qs2 = find_by_topic("Nonexistent Topic");
        assert!(qs2.is_empty(), "Unknown topic should return empty");
    }

    #[test]
    fn test_all_questions_have_correct_answer_in_options() {
        for q in QUESTIONS.iter() {
            assert!(
                q.options.contains(&q.correct_answer),
                "Question '{}' correct answer '{}' not in options {:?}",
                q.question_text, q.correct_answer, q.options
            );
        }
    }

    #[test]
    fn test_question_types_valid() {
        for q in QUESTIONS.iter() {
            assert!(
                ["recall", "applied", "synthesis"].contains(&q.question_type),
                "Invalid question type '{}' for '{}'", q.question_type, q.question_text
            );
        }
    }
}
